"""Present frozen completed replay aggregates; no inference or new scoring."""
import json
from pathlib import Path
OUT=Path(__file__).resolve().parent
def pct(x):return f'{100*x:.2f}%' if x is not None else 'NA'
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|']+['| '+' | '.join(str(x) for x in row)+' |' for row in rows])
def main():
 s=json.loads((OUT/'SUMMARY.json').read_text());parts=['# Frozen replay result tables','P1 is primary; P2 is research validation; P3 is secondary historical context. No pooled prevalence. All denominators include eligible unresolved rows unless explicitly labeled scorable.']
 groups=[(p,g) for p,g in s['strata'].items()]
 parts+=['## Population and official outcomes',table(['Stratum','Eligible runs','Tasks','Scorable pairs','Exact 0→1','Exact 1→0','Modification +≥.01','Modification −≥.01','Regression +≥.01','Regression −≥.01'],[[p,g['eligible'],g['tasks'],g['scorable_pairs'],g['exact_0_to_1'],g['exact_1_to_0'],g['modification_increase'],g['modification_decrease'],g['regression_increase'],g['regression_decrease']] for p,g in groups])]
 parts+=['## Cache attribution',table(['Stratum','Cache-only recovery runs','All-run rate','Historically score-compatible runs','Affected tasks','Task rate','Unresolved historical run bound'],[[p,g['cache_only_recoveries'],pct(g['cache_only_fraction_all_eligible']),g['historically_proven_recoveries'],g['cache_only_affected_tasks'],pct(g['task_any_cache_only_fraction']),pct(g['unresolved_case_bound']['run_lower'])+'–'+pct(g['unresolved_case_bound']['run_upper'])] for p,g in groups])]
 for p,g in groups:
  parts+=['## '+p+' categories',table(['Category','Runs / tasks','Scorable','Cache-only runs / tasks','All-run rate','Task rate','Exact + / −','Modification + / −','Harms / unresolved'],[[c,f"{d['eligible']} / {d['tasks']}",d['scorable_pairs'],f"{d['cache_only_recoveries']} / {d['cache_only_affected_tasks']}",pct(d['cache_only_fraction_all_eligible']),pct(d['task_any_cache_only_fraction']),f"{d['exact_0_to_1']} / {d['exact_1_to_0']}",f"{d['modification_increase']} / {d['modification_decrease']}",f"{d['classifications'].get('RECALC_REGRESSION',0)} / {d['unscorable']}"] for c,d in s['categories'][p].items()])]
  parts+=['### '+p+' classifications',table(['Class','Runs'],sorted(g['classifications'].items())),'### '+p+' identity',table(['Identity','Runs'],sorted(g['formula_identity'].items())),'### '+p+' continuous score deltas',table(['Score','N','Min','p10','Median','p90','Max','Mean','Sum'],[[k]+[v.get(x,'NA') for x in ['n','minimum','p10','median','p90','maximum','mean','sum']] for k,v in g['continuous_delta_distributions'].items()])]
 parts+=['## Formula cache census',table(['Stratum','V0 inspected','Formula workbooks','Missing-cache workbooks','Replay-stale workbooks','V0 formula cells','V0 missing cells','V0 error cells'],[[p,g['V0_cache_inspection_completed'],g['workbooks_with_formula_cells'],g['workbooks_with_missing_formula_caches'],g['workbooks_with_replay_changed_present_caches'],g['formula_cells_V0_total'],g['formula_cells_V0_cache_absent'],g['formula_cells_V0_cache_error']] for p,g in groups]),'A present cache that changed is stale relative to this LibreOffice execution; it is not independently established to have been wrong. Missing and changed-present workbooks can overlap.']
 parts+=['## Original score reproduction',table(['Stratum','Returned tuple reproduced','Returned tuple different','Unavailable','Archived / unverified'],[[p,g['score_reproduction'].get('True',0),g['score_reproduction'].get('False',0),g['score_reproduction'].get('None',0),str(g['byte_linkage'])] for p,g in groups]),'Historical evaluator source versions are unavailable. Numeric reproduction does not establish historical implementation identity.']
 parts+=['## P2 experiments',table(['Experiment','Runs / tasks','Scorable','Strong / historical gains','Exact + / −','Modification + / −','Harms'],[[k,f"{g['eligible']} / {g['tasks']}",g['scorable_pairs'],f"{g['cache_only_recoveries']} / {g['historically_proven_recoveries']}",f"{g['exact_0_to_1']} / {g['exact_1_to_0']}",f"{g['modification_increase']} / {g['modification_decrease']}",g['classifications'].get('RECALC_REGRESSION',0)] for k,g in s['experiments'].items() if not k.startswith('benchmark-data/')])]
 parts+=['## Task clustering',table(['Stratum','Task','Runs','Scorable','Cache-only runs','Historically score-compatible gains','Exact + / −'],[[g['stratum'],g['task'],g['eligible'],g['scorable_pairs'],g['cache_only_recoveries'],g['historically_proven_recoveries'],f"{g['exact_0_to_1']} / {g['exact_1_to_0']}"] for g in s['task_clustering']]),'Run identities are in SUMMARY.json and BASELINE_CORRECTION_LEDGER.jsonl. No independent-run significance claims are made.']
 (OUT/'RESULT_TABLES.md').write_text('\n\n'.join(parts)+'\n')
if __name__=='__main__':main()
